E("s9f-u1-constellation-figure", 1, ["SC9.1.1"], 1, "var", varset([
  function () { var q = mcq("Le schéma montre un motif d'étoiles familier : sept étoiles brillantes qui forment une louche, avec un manche courbé qui s'éloigne d'un bol. Quel énoncé au sujet de ce motif est exact?", "C'est un astérisme appelé la Grande Casserole, situé dans la constellation de la Grande Ourse", ["C'est une constellation appelée la Grande Casserole, distincte de la Grande Ourse", "C'est un astérisme appelé la Petite Casserole, situé dans la constellation de la Petite Ourse", "C'est la ceinture d'Orion, un astérisme situé dans la constellation d'Orion"], "Une constellation est une région reconnue du ciel, tandis qu'un astérisme est un motif plus petit et bien connu à l'intérieur d'une constellation. Le motif en louche est la Grande Casserole, un astérisme dans la Grande Ourse. La Petite Casserole se trouve dans la Petite Ourse, et la ceinture d'Orion est un alignement de trois étoiles, pas une louche.", {}); q.figure = s9fu1ConstellationSVG(); return q; }
]), ["Décide d'abord si le motif nommé est une constellation entière ou un motif à l'intérieur d'une constellation.", "La forme de louche appartient à la Grande Ourse."]);
E("s9f-u1-orbit-meaning", 1, ["SC9.1.1"], 1, "var", varset([
  function () { var q = mcq("Le schéma montre un corps qui suit un trajet fermé et répétitif autour d'un corps plus gros. Qu'est-ce qui maintient le corps en mouvement sur ce trajet?", "La gravité entre les deux corps le maintient sur son orbite régulière", ["Un courant de vent solaire le pousse autour du corps plus gros", "La rotation du corps plus gros l'entraîne par frottement continu", "La pression de la lumière du corps plus gros le retient sur le trajet"], "Les corps célestes se déplacent sur des trajets cycliques appelés orbites, et ces orbites résultent des forces gravitationnelles. La gravité attire le corps en mouvement vers le corps plus gros pendant que son mouvement vers l'avant le fait continuer, de sorte qu'il suit sans cesse le même trajet fermé.", {}); q.figure = s9fu1OrbitSVG(); return q; }
]), ["Cherche la force qui agit à distance entre les deux corps.", "C'est la même force qui retient la Lune autour de la Terre."]);
E("s9f-u1-motion-cause", 1, ["SC9.1.1"], 1, "var", varset([
  function () { return mcq("Vu de la Terre, le Soleil semble se lever à l'est et se coucher à l'ouest chaque jour. Quelle est la vraie cause de ce mouvement apparent quotidien?", "La Terre tourne sur son axe, ce qui fait paraître le Soleil en mouvement dans le ciel", ["Le Soleil tourne autour de la Terre une fois par jour, d'est en ouest", "L'axe de la Terre oscille chaque jour et déplace la position du Soleil", "L'orbite de la Lune entraîne le Soleil à travers le ciel chaque jour"], "Le mouvement apparent est le mouvement que les objets semblent avoir vu de la Terre. La rotation quotidienne de la Terre sur son axe fait paraître le Soleil, la Lune et les étoiles se déplacer dans le ciel, même si c'est la Terre qui bouge.", {}); }
]), ["Demande-toi quel corps bouge vraiment dans cette situation.", "Le lever et le coucher se répètent toutes les 24 heures, comme la rotation terrestre."]);
E("s9f-u1-wander", 1, ["SC9.1.1"], 2, "gen", function () {
  var c = pick([
    { p: "Les observateurs anciens ont remarqué qu'une « étoile errante » se déplaçait lentement parmi les étoiles fixes, nuit après nuit. De quoi s'agissait-il le plus probablement?", k: "D'une planète, dont l'orbite la déplace par rapport aux étoiles lointaines", d: ["D'une comète, dont la queue la déplace par rapport aux étoiles lointaines", "D'un météore, dont la chute le déplace par rapport aux étoiles lointaines", "D'une étoile variable, dont l'éclat la déplace parmi les étoiles lointaines"], s: "Le mot planète vient d'un mot qui signifie « errant ». Les planètes orbitent autour du Soleil, donc leur position parmi les étoiles d'arrière-plan change de nuit en nuit. Les étoiles elles-mêmes gardent des positions fixes les unes par rapport aux autres." },
    { p: "Une étoile semble décrire un petit cercle dans le ciel pendant une nuit d'observation. Quelle explication est la meilleure?", k: "La rotation de la Terre fait paraître l'étoile en mouvement circulaire apparent", d: ["L'étoile orbite autour de la Terre et décrit un vrai cercle chaque nuit", "L'orbite de la Terre déplace l'étoile en cercle au fil des saisons", "La Lune attire l'étoile et la fait décrire un cercle chaque nuit"], s: "Près du pôle céleste, les étoiles semblent tourner en cercle pendant la nuit parce que la Terre tourne sous elles. C'est un mouvement apparent : c'est l'observateur qui bouge, pas l'étoile." }
  ]);
  return mcq(c.p, c.k, c.d, c.s, {});
}, ["Sépare le mouvement réel du mouvement apparent vu de la Terre.", "Les étoiles fixes gardent leurs positions relatives; ce qui change révèle le vrai mouvement."]);
E("s9f-u1-moon-motion", 1, ["SC9.1.1"], 3, "var", varset([
  function () { return mcq("La Lune se lève environ 50 minutes plus tard chaque nuit. Quelle combinaison explique le mieux ce retard régulier?", "La Lune avance sur son orbite, donc la Terre doit tourner un peu plus pour la revoir", ["La rotation de la Terre ralentit un peu chaque nuit, donc la Lune paraît en retard", "L'orbite de la Lune s'élargit chaque nuit, donc sa lumière met plus de temps à arriver", "Les marées freinent la Lune chaque nuit, donc elle traverse le ciel plus lentement"], "La Lune met environ 27,3 jours à orbiter autour de la Terre. Chaque jour, elle avance sur son orbite; la Terre doit donc tourner un peu au-delà d'un tour complet avant que la Lune réapparaisse au même endroit du ciel, ce qui retarde son lever d'environ 50 minutes par nuit.", {}); }
]), ["Deux mouvements se combinent : la rotation de la Terre et l'orbite de la Lune.", "Pense à la position de la Lune sur son orbite après une journée complète."]);
E("s9f-u1-cr-apparent", 1, ["SC9.1.1"], 2, "var", varset([
  function () { return textq("Explique la différence entre le mouvement réel et le mouvement apparent, puis applique-la à DEUX exemples : le trajet quotidien du Soleil dans le ciel et le déplacement lent d'une planète parmi les étoiles. (3 points)", ["mouvement apparent : mouvement vu de la Terre qui ne correspond pas au vrai mouvement de l'objet", "Soleil : semble tourner autour de la Terre, mais c'est la rotation terrestre qui le cause", "planète : son déplacement parmi les étoiles est réel, causé par son orbite autour du Soleil"], "<b>Réponse modèle :</b> Le mouvement apparent est le mouvement qu'un objet semble avoir vu de la Terre, alors que le mouvement réel est le déplacement véritable de l'objet. Le Soleil semble traverser le ciel chaque jour, mais ce mouvement apparent vient de la rotation de la Terre sur son axe; le Soleil ne tourne pas autour de la Terre. En revanche, une planète qui se déplace lentement parmi les étoiles montre un mouvement réel : elle avance vraiment sur son orbite autour du Soleil, ce qui change sa position par rapport aux étoiles lointaines.<br><br><b>Points d'attribution :</b> 1 point pour la distinction claire entre mouvement apparent et mouvement réel. 1 point pour l'exemple du Soleil correctement expliqué par la rotation de la Terre. 1 point pour l'exemple de la planète correctement expliqué par son orbite.", {}); }
]), ["Pense à la structure de la réponse : une idée complète par point.", "Relis la question et vérifie que chaque partie demandée est traitée."]);
E("s9f-u1-thinker-match", 1, ["SC9.1.2"], 1, "var", varset([
  function () { return mcq("Quel penseur a proposé le modèle héliocentrique, où le Soleil est au centre et les planètes tournent autour de lui?", "Nicolas Copernic, qui a placé le Soleil au centre du système décrit", ["Claude Ptolémée, qui a placé le Soleil au centre du système décrit", "Tycho Brahe, qui a placé le Soleil au centre du système décrit", "Aristote, qui a placé le Soleil au centre du système décrit"], "Copernic a proposé le modèle héliocentrique au 16e siècle. Ptolémée et Aristote défendaient des modèles géocentriques où la Terre est au centre, et Brahe a proposé un modèle mixte où les planètes tournent autour du Soleil, mais le Soleil tourne autour de la Terre.", {}); }
]), ["Le préfixe « hélio » renvoie au Soleil.", "Ce penseur a travaillé au 16e siècle, bien après Ptolémée."]);
E("s9f-u1-geo-helio", 1, ["SC9.1.2"], 1, "var", varset([
  function () { return mcq("Quelle observation, faite au télescope, appuyait le modèle héliocentrique contre le modèle géocentrique?", "Les phases complètes de Vénus, impossibles si Vénus tournait autour de la Terre", ["Les taches solaires mobiles, impossibles si Vénus tournait autour de la Terre", "Les anneaux de Saturne, impossibles si Vénus tournait autour de la Terre", "Les lunes de Jupiter, impossibles si Vénus tournait autour de la Terre"], "Galilée a observé que Vénus montre un cycle complet de phases, comme la Lune. Cela n'est possible que si Vénus orbite autour du Soleil et que nous voyons sa face éclairée sous des angles changeants; dans le modèle géocentrique, Vénus resterait toujours entre la Terre et le Soleil et ne montrerait jamais une phase pleine.", {}); }
]), ["Pense à ce que les phases révèlent sur l'orbite de Vénus.", "Les phases complètes exigent que Vénus passe derrière le Soleil vu de la Terre."]);
E("s9f-u1-kepler-galileo", 1, ["SC9.1.2"], 2, "var", varset([
  function () { return mcq("Quel énoncé décrit correctement l'apport respectif de Kepler et de Galilée, sans nommer de lois?", "Kepler a déterminé que les planètes suivent des orbites elliptiques; Galilée a appuyé le modèle par ses observations au télescope", ["Galilée a déterminé que les planètes suivent des orbites elliptiques; Kepler a appuyé le modèle par ses observations au télescope", "Kepler a construit le premier télescope astronomique; Galilée a calculé les orbites elliptiques des planètes connues", "Galilée a placé la Terre au centre du système; Kepler a placé le Soleil au centre du système solaire"], "Kepler, à partir des données précises de Brahe, a déterminé que les orbites planétaires sont des ellipses. Galilée, avec le télescope, a fourni des observations qui appuyaient le modèle héliocentrique, comme les phases de Vénus et les lunes de Jupiter. Les deux apports se complètent : le calcul d'un côté, l'observation de l'autre.", {}); }
]), ["L'un travaillait surtout avec des données et des calculs, l'autre avec un instrument nouveau.", "Brahe a fourni les données que Kepler a utilisées."]);
E("s9f-u1-models-judgement", 1, ["SC9.1.2"], 3, "var", varset([
  function () { return mcq("Un modèle place la Terre au centre et explique le mouvement des planètes par des cercles ajoutés aux orbites. Un autre place le Soleil au centre et explique les mêmes mouvements plus simplement. Pourquoi les scientifiques ont-ils fini par préférer le second modèle?", "Parce qu'il expliquait les observations avec moins d'ajouts artificiels et prévoyait mieux les positions", ["Parce qu'il était plus ancien et que les modèles anciens sont toujours préférés en sciences", "Parce qu'il plaçait la Terre au centre, ce qui correspondait aux croyances de l'époque", "Parce qu'il exigeait plus de cercles ajoutés, ce qui le rendait plus précis en tout temps"], "Un bon modèle explique les observations de façon simple et fait des prévisions justes. Le modèle géocentrique accumulait les cercles ajoutés pour sauver les apparences, tandis que le modèle héliocentrique expliquait les mêmes mouvements, comme le mouvement rétrograde, de façon naturelle et plus simple.", {}); }
]), ["Compare les deux modèles sur deux critères : simplicité et prévisions.", "Le mouvement rétrograde devient simple quand la Terre elle-même est en mouvement."]);
E("s9f-u1-cr-thinkers", 1, ["SC9.1.2"], 2, "var", varset([
  function () { return textq("Compare le modèle géocentrique et le modèle héliocentrique : nomme le corps au centre de chacun, nomme un défenseur de chacun, et donne UNE observation qui a aidé à trancher entre les deux. (3 points)", ["géocentrique : Terre au centre, défendu par Ptolémée", "héliocentrique : Soleil au centre, proposé par Copernic", "observation : phases complètes de Vénus observées par Galilée, ou lunes de Jupiter"], "<b>Réponse modèle :</b> Dans le modèle géocentrique, défendu par Ptolémée, la Terre est immobile au centre et le Soleil, la Lune et les planètes tournent autour d'elle. Dans le modèle héliocentrique, proposé par Copernic, le Soleil est au centre et la Terre est une planète comme les autres qui tourne autour de lui. Les observations de Galilée au télescope ont aidé à trancher : Vénus montre un cycle complet de phases, ce qui n'est possible que si elle orbite autour du Soleil.<br><br><b>Points d'attribution :</b> 1 point pour le modèle géocentrique correctement décrit avec son défenseur. 1 point pour le modèle héliocentrique correctement décrit avec son défenseur. 1 point pour une observation pertinente qui appuie le modèle héliocentrique.", {}); }
]), ["Pense à la structure de la réponse : une idée complète par point.", "Relis la question et vérifie que chaque partie demandée est traitée."]);
E("s9f-u1-sun-makeup", 1, ["SC9.1.3"], 1, "var", varset([
  function () { return mcq("De quoi le Soleil est-il principalement composé?", "D'hydrogène et d'hélium, des gaz très chauds en fusion continue", ["De roche fondue et de fer, comme le noyau de la Terre", "D'oxygène et d'azote, comme l'atmosphère de la Terre", "De carbone et d'eau, comme la matière des êtres vivants"], "Le Soleil est une étoile composée surtout d'hydrogène et d'hélium. En son centre, la fusion transforme l'hydrogène en hélium et libère l'énergie qui nous parvient sous forme de lumière et de chaleur.", {}); }
]), ["Le Soleil est une étoile, pas une planète rocheuse.", "Son carburant est le gaz le plus léger de l'Univers."]);
